451	// occasional horizontal slice shifts and blocks over the viewport
452	function glitcher(source, rnd) {
453	  const items = []; let next = 1;
454	  return (ctx, w, h, dpr, t) => {
455	    if (t > next) {
456	      for (let k = 0, n = 1 + Math.floor(rnd() * 4); k < n; k++) {
457	        const type = rnd() < 0.6 ? "slice" : "bar";
458	        items.push({ type, x: rnd() * w * 0.85, y: rnd() * h * 0.85, w: type === "bar" ? w * (0.2 + rnd() * 0.5) : 30 + rnd() * 180, h: type === "bar" ? 1 + rnd() * 2 : 6 + rnd() * 40, shift: (rnd() - 0.5) * 60, until: t + 0.06 + rnd() * 0.35 });
459	      }
460	      next = t + 0.6 + rnd() * 2.4;
461	    }
462	    for (let k = items.length - 1; k >= 0; k--) {
463	      const g = items[k];
464	      if (t > g.until) { items.splice(k, 1); continue; }
465	      if (g.type === "slice") { try { ctx.drawImage(source, g.x * dpr, g.y * dpr, g.w * dpr, g.h * dpr, g.x + g.shift, g.y, g.w, g.h); } catch { /* canvas not ready */ } }
