#!/usr/bin/env python3
"""Build ui/data/fence.json and the terrain binaries from real git history and resolver output.

usage: build_data.py <cli clone> <trace_at_created.json> <cli_issues.json> <out dir> [featured issue]

Everything here is read from git or from data/ files produced by fence/resolve.py. Nothing is invented:
panels whose source does not exist yet (agent verdicts, run costs) are left out of the JSON.
"""
import collections, datetime, json, re, struct, subprocess, sys

repo, trace_path, issues_path, out = sys.argv[1:5]
FEATURED = int(sys.argv[5]) if len(sys.argv) > 5 else 2256
W, H = 200, 160
PREFIX = "cmd/entire/cli/"


def git(*a):
    return subprocess.run(["git", "-C", repo, *a], capture_output=True, text=True, errors="replace").stdout


def month_index(d, first):
    return (d.year - first.year) * 12 + d.month - first.month


# ---- commits: date, checkpoint trailer, per-file added/deleted lines
commits, cur = [], None
log = git("log", "--reverse", "--format=@%H|%as|%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2C)|%s", "--numstat", "--", "cmd/entire/cli")
for line in log.splitlines():
    if line.startswith("@"):
        h, date, ck, subj = line[1:].split("|", 3)
@font-face { font-family: Plex; src: url(fonts/IBMPlexMono-Light.ttf) format("truetype"); font-weight: 300; }

:root {
  --bg: #030304;
  --fg: #e9e9e9;
  --dim: rgba(255, 255, 255, .45);
  --faint: rgba(255, 255, 255, .22);
  --line: rgba(255, 255, 255, .13);
  --amber: #ff9a3c;
  --gap: 10px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background: radial-gradient(120% 90% at 50% 40%, #0b0b0d 0%, var(--bg) 70%);
  color: var(--fg);
  font: 300 10px/1.4 Plex, ui-monospace, monospace;
  letter-spacing: .04em;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}
/* scanlines over everything */
body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 20;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, .025) 0 1px, transparent 1px 3px);
}
#grain { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; opacity: .055; mix-blend-mode: screen; z-index: 21; }

/* ---- frame: header / three columns / footer ---- */
.frame {
  height: 100vh; display: grid; gap: var(--gap); padding: 12px 14px;
  grid-template-columns: 320px minmax(0, 1fr) 340px;
  grid-template-rows: 44px minmax(0, 1fr) 18px;
}
.top {
  grid-column: 1 / -1; display: grid; grid-template-columns: 320px 1fr 340px; gap: var(--gap);
  align-items: center; border-bottom: 1px solid var(--line); position: relative;
}
.top::after { content: ""; position: absolute; left: 0; bottom: -1px; width: 140px; height: 1px; background: var(--fg); }
.brand { display: flex; align-items: center; gap: 12px; }
.brand svg { width: 28px; height: 28px; }
.brand b { display: block; font-size: 17px; letter-spacing: .32em; font-weight: 300; }
.brand small { display: block; font-size: 7.5px; letter-spacing: .3em; color: var(--dim); }
.ticker { display: flex; justify-content: center; gap: 36px; color: var(--dim); font-size: 9px; white-space: nowrap; overflow: hidden; }
.clock { display: flex; justify-content: flex-end; align-items: center; gap: 18px; }
.clock small { display: block; color: var(--dim); font-size: 8px; letter-spacing: .2em; text-align: right; }
.clock b { display: block; font-size: 18px; font-weight: 300; letter-spacing: .12em; text-align: right; }
.legend { display: grid; grid-template-columns: repeat(2, auto); gap: 2px 12px; color: var(--dim); font-size: 8px; }
.legend i, .bottom i { display: inline-block; width: 6px; height: 6px; background: var(--fg); margin-right: 5px; vertical-align: 0; }
.legend i.amber, .bottom i.amber { background: var(--amber); }

.col { display: flex; flex-direction: column; gap: var(--gap); min-height: 0; }
.center { display: grid; grid-template-rows: minmax(0, 1fr) 168px; gap: var(--gap); min-width: 0; min-height: 0; }
.row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--gap); min-height: 0; }

/* ---- panel: hairline box with two corner brackets ---- */
.panel {
  position: relative; border: 1px solid var(--line); display: flex; flex-direction: column; min-height: 0; flex: 1;
  background: linear-gradient(180deg, #ffffff06, #ffffff02);
}
.panel::before, .panel::after { content: ""; position: absolute; width: 9px; height: 9px; border: 1px solid var(--fg); pointer-events: none; z-index: 3; }
.panel::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.panel::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }
.panel > header { display: flex; align-items: center; gap: 8px; padding: 7px 10px 4px; letter-spacing: .18em; font-size: 9.5px; position: relative; z-index: 2; white-space: nowrap; }
.panel > header small { color: var(--faint); font-size: 7.5px; letter-spacing: .16em; margin-left: auto; }
.tag { display: inline-grid; place-items: center; min-width: 13px; height: 13px; padding: 0 2px; border: 1px solid var(--dim); font-size: 7.5px; letter-spacing: 0; }
.body { position: relative; flex: 1; min-height: 0; margin: 2px 10px 10px; }
.body > canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

/* A · run replay */
.telemetry { flex: 0 0 auto; }
.telemetry .body { display: grid; grid-template-columns: 84px 1fr; gap: 12px; height: 92px; flex: none; }
.telemetry .radar { position: relative; }
.telemetry .radar canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.kpis { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; align-content: center; }
.kpis small { display: block; font-size: 7.5px; color: var(--dim); letter-spacing: .18em; }
.kpis b { display: block; font-size: 17px; font-weight: 300; letter-spacing: .06em; white-space: nowrap; }
.kpis b.small { font-size: 12px; padding-top: 4px; }

/* B · evidence chain */
.checkpoints .body { overflow: hidden; }
table { width: 100%; border-collapse: collapse; font-size: 9px; }
th { text-align: left; font-weight: 300; color: var(--faint); font-size: 7.5px; letter-spacing: .16em; padding: 0 0 4px; border-bottom: 1px solid var(--line); }
td { padding: 3.5px 0; border-bottom: 1px dashed rgba(255, 255, 255, .06); white-space: nowrap; color: rgba(255, 255, 255, .7); }
td.num, th.num { text-align: right; padding-left: 8px; font-variant-numeric: tabular-nums; }
td.name { max-width: 128px; overflow: hidden; text-overflow: ellipsis; }
#checkpoints tr.on td { color: var(--fg); background: rgba(255, 154, 60, .08); }
#checkpoints tr.on td:first-child { color: var(--amber); }
#checkpoints tr.pending td { color: rgba(255, 255, 255, .3); }
#checkpoints td.ck { color: var(--amber); }

/* 01 · evidence trail */
.viewport > header small { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 60%; }
.stages { display: flex; position: relative; margin: 0 10px 6px; border: 1px solid var(--line); flex: none; }
.stage { flex: 1; min-width: 0; padding: 4px 8px 5px; border-left: 1px solid var(--line); }
.stage:first-child { border-left: 0; }
.stage small { display: block; font-size: 7px; letter-spacing: .18em; color: var(--faint); white-space: nowrap; }
.stage b { display: block; font-weight: 300; font-size: 10px; letter-spacing: .06em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--fg); }
.stage.live b { color: var(--amber); }
.stage.on { background: rgba(255, 154, 60, .08); }
.stage.on b { color: var(--amber); }
.stages .bar { position: absolute; left: 0; bottom: -1px; height: 1px; background: var(--amber); width: 0; transition: width .6s linear; }
.scene { position: relative; flex: 1; min-height: 0; }
.scene > canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.scene > canvas#scene { cursor: grab; }
.scene > canvas#scene:active { cursor: grabbing; }
.scene > canvas#scene-hud { pointer-events: none; }
.card {
  position: absolute; left: 12px; top: 8px; width: 280px; z-index: 4; pointer-events: none;
  background: rgba(3, 3, 4, .82); border: 1px solid var(--line); padding: 8px 10px 9px;
}
.card::before, .card::after { content: ""; position: absolute; width: 7px; height: 7px; border: 1px solid var(--amber); }
.card::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.card::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }
.card-head { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
.card-head b { font-weight: 300; font-size: 15px; letter-spacing: .08em; color: var(--amber); }
.card-head span { font-size: 10px; letter-spacing: .1em; }
.card-head em { font-style: normal; margin-left: auto; font-size: 8px; color: var(--dim); letter-spacing: .14em; }
.card-subj { font-size: 10px; letter-spacing: .04em; line-height: 1.35; margin: 4px 0 5px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-meta { display: flex; justify-content: space-between; gap: 10px; font-size: 8px; letter-spacing: .12em; color: var(--dim); white-space: nowrap; }
.card-meta span:first-child { overflow: hidden; text-overflow: ellipsis; }
.card-ck { font-size: 8px; letter-spacing: .12em; color: var(--amber); margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card-ck.none { color: var(--faint); }
.card-prompt { margin-top: 6px; padding-top: 5px; border-top: 1px dashed rgba(255, 255, 255, .1); }
.card-prompt small { display: block; font-size: 7px; letter-spacing: .2em; color: var(--faint); margin-bottom: 2px; }
.card-prompt p { font-size: 8.5px; line-height: 1.4; color: rgba(255, 255, 255, .7); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.scene .hint { position: absolute; right: 14px; bottom: 26px; color: var(--faint); font-size: 8px; letter-spacing: .16em; z-index: 2; pointer-events: none; }

/* G · sphere */
.globe-panel { flex: 1.45; }
.globe-panel .body > canvas#globe-hud { pointer-events: none; }
.globe-panel .readout { position: absolute; left: 0; bottom: 0; color: var(--dim); font-size: 8px; letter-spacing: .14em; z-index: 2; }
.globe-panel .readout.right { left: auto; right: 0; color: var(--amber); }

/* E · profile readout */
.profile-panel .big { position: absolute; right: 0; top: -2px; font-size: 18px; letter-spacing: .06em; text-align: right; z-index: 2; }
.profile-panel .big small { display: block; font-size: 7.5px; color: var(--dim); letter-spacing: .2em; }

/* I · two result lists */
.results { position: absolute; inset: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 8px; }
.results ol { list-style: none; min-width: 0; }
.results h4 { font-weight: 300; font-size: 7.5px; letter-spacing: .2em; color: var(--faint); margin-bottom: 3px; }
.results li { display: grid; grid-template-columns: 12px 1fr auto; gap: 6px; padding: 1.5px 0; color: rgba(255, 255, 255, .7); white-space: nowrap; }
.results li span:nth-child(2) { overflow: hidden; text-overflow: ellipsis; }
.results li.done { color: var(--fg); }
.results li.done span:first-child { color: var(--amber); }
.results small { color: var(--faint); }

/* J · log */
.log-panel { flex: .9; }
#log { list-style: none; position: absolute; inset: 0; overflow: hidden; font-size: 8.5px; }
#log li { display: flex; gap: 10px; padding: 2px 0; color: #ffffffb3; white-space: nowrap; }
#log li:first-child { color: var(--fg); }
#log li.warn { color: var(--amber); }
#log time { color: var(--faint); }

/* footer strip */
.bottom {
  grid-column: 1 / -1; display: flex; align-items: center; gap: 16px; color: var(--dim); font-size: 8px;
  border-top: 1px solid var(--line); padding-top: 4px; overflow: hidden; white-space: nowrap;
}
.bottom b { font-weight: 300; }
.bottom em { margin-left: auto; font-style: normal; color: var(--faint); }
.bottom .copy { font-weight: 300; color: var(--fg); letter-spacing: .12em; flex: none; }

@media (max-width: 1100px) {
  body { overflow: auto; }
  .frame { height: auto; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto; padding: 12px 16px; }
  .top { grid-template-columns: 1fr auto; padding-bottom: 8px; }
  .ticker, .legend { display: none; }
  .center { order: -1; grid-template-rows: 78vh 168px; }
  .card { width: min(300px, 70%); }
  .scene .hint { display: none; }
  .col .panel { min-height: 200px; }
  .telemetry { min-height: 0 !important; }
  .bottom em { display: none; }
}
@media (max-width: 560px) {
  .row { display: contents; }
  .center { grid-template-rows: 64vh 168px 168px; }
}

